css:
.loader {
  position: relative;
  width: 24px;
  height: 52px;
}
.loader::before {
  content: "";
  position: absolute;
  top: 0;
  left: 50%;
  width: 2px;
  margin-left: -1px;
  background: #c7d2fe;
  animation: str 1s ease-in-out infinite;
}
.loader i {
  position: absolute;
  left: 50%;
  width: 22px;
  height: 22px;
  margin-left: -11px;
  border-radius: 50%;
  background: #6366f1;
  box-shadow: inset 0 0 0 3px #4338ca;
  animation: drop 1s ease-in-out infinite, spin 0.5s linear infinite;
}
@keyframes drop {
  0%, 100% { top: 8px; }
  50% { top: 28px; }
}
@keyframes str {
  0%, 100% { height: 16px; }
  50% { height: 36px; }
}
@keyframes spin { to { transform: rotate(360deg); } }
